MORE=pathlib.Path(__file__).with_name('group-c-more.txt')
if MORE.exists(): RAW += '\n' + MORE.read_text()

def build():
 briefs={x['index']:x for x in json.loads((BASE/'briefs.json').read_text())}
 out=BASE/'source'/'content';out.mkdir(exist_ok=True)
 (BASE/'notes').mkdir(exist_ok=True)
 count=0
 for chunk in RAW.strip().split('@@')[1:]:
  head,*rest=chunk.strip().splitlines();idx,tag,caption=head.split('|');idx=int(idx);b=briefs[idx]
  pairs=re.findall(r'\[([^\]]+)\]\n(.*?)(?=\n\[|\Z)','\n'.join(rest),re.S)
  sections=[{'heading':h.strip(),'text':' '.join(t.split())} for h,t in pairs[:4]]
  deep=' '.join(pairs[4][1].split())
  entry={'index':idx,'slug':b['slug'],'word':b['word'],'pronunciation':'','tagline':tag,'definition':b['definition'],'etymology':b['etymology'],'sections':sections,'literary':b['literary_sentence'],'art_caption':caption,'accent':['AD793B','397F79','95604A','766296'][idx%4],'theme':'201A32'}
  (out/f"{idx:03d}-{b['slug']}.json").write_text(json.dumps(entry,ensure_ascii=False,indent=2)+'\n')
  lines=[f"# {idx:03d} · {b['word']}",tag,'## Definition',b['definition'],'## Etymology',b['etymology']]
  for s in sections:lines += ['## '+s['heading'],s['text']]
  lines += ['## Further exploration',b['explanation'],deep,'## Original literary sentence',b['literary_sentence'],'## Reading the image',caption,'Artwork: original local procedural sculpture, rendered from native geometry.']
  (BASE/'notes'/f"{idx:03d}-{b['slug']}.md").write_text('\n\n'.join(lines)+'\n')
  wc=[len(re.findall(r"\S+",s['text'])) for s in sections]
  nw=len(re.findall(r'\S+','\n'.join(lines)));extra=len((b['explanation']+' '+deep).split())
  print(idx,b['slug'],'sections',wc,'notes',nw,'extra',extra,flush=True)
  count+=1
 print('Built',count,'entries')
if __name__=='__main__':build()
